<script setup lang="ts">
import { useApi } from '~/composables/useApi';

import type { PriceComparison, PriceSummary } from '~/types/api'
import { money,numberTR } from '~/utils/format'
const api=useApi();const propertyType=ref('apartment');const areaType=ref('net');const minimumListings=ref(5);const provinceId=ref('');const districtId=ref('');const neighborhoodId=ref('');const summary=ref<PriceSummary|null>(null);const result=ref<PriceComparison|null>(null);const state=ref<'loading'|'error'|'success'>('loading');const error=ref('')
async function load(){state.value='loading';error.value='';try{const filters={property_type:propertyType.value,area_type:areaType.value,minimum_listings:minimumListings.value,province_id:provinceId.value||undefined,district_id:districtId.value||undefined,neighborhood_id:neighborhoodId.value||undefined};const [s,c]=await Promise.all([api.priceSummary(filters),api.compare({...filters,group_by:'neighborhood'})]);summary.value=s;result.value=c;state.value='success'}catch(e){state.value='error';error.value=e instanceof Error?e.message:'Mahalle analizi alınamadı.'}}
await load();const maxCount=computed(()=>Math.max(1,...(result.value?.groups.map(g=>g.listing_count)||[])))
</script>
<template><div class="page-heading"><div><p class="eyebrow">PİYASA İSTİHBARATI</p><h1>Mahalle bazlı analiz</h1><p>Seçili gayrimenkul türünde mahalleleri ilan fiyatı ve m² fiyatı üzerinden karşılaştırın.</p></div><button class="button button-secondary" @click="load">↻ Yenile</button></div><section class="filter-card"><div class="filter-grid"><div class="field"><label>Gayrimenkul türü</label><select v-model="propertyType"><option value="apartment">Daire</option><option value="detached_house">Müstakil ev</option><option value="villa">Villa</option><option value="residential_land">İmarlı arsa</option><option value="farmland">Tarla</option></select></div><div class="field"><label>Konut alan türü</label><select v-model="areaType"><option value="net">Net m²</option><option value="gross">Brüt m²</option></select><small>Arsa ve tarla için parsel alanı kullanılır.</small></div><div class="field"><label>İl ID (isteğe bağlı)</label><input v-model="provinceId" type="number" min="1" placeholder="İl ID"/></div><div class="field"><label>İlçe ID (isteğe bağlı)</label><input v-model="districtId" type="number" min="1" placeholder="İlçe ID"/></div><div class="field"><label>Mahalle ID (isteğe bağlı)</label><input v-model="neighborhoodId" type="number" min="1" placeholder="Mahalle ID"/></div><div class="field"><label>Minimum ilan eşiği</label><input v-model.number="minimumListings" type="number" min="1" max="100"/></div></div><div class="filter-actions"><span class="muted">Filtreler birlikte uygulanır; konut ve arazi metrikleri karıştırılmaz.</span><button class="button button-primary" @click="load">Analizi çalıştır →</button></div></section><div v-if="state==='success'&&summary?.reliability==='limited'" class="alert alert-warning">{{ summary.reliability_note }}</div><section class="panel"><div class="panel-header"><div><h2>Mahalle karşılaştırması</h2><p>İlan fiyatlarıdır; gerçekleşmiş satış fiyatları değildir.</p></div><span class="chip">{{ result?.groups.length||0 }} grup</span></div><StatePanel v-if="state==='loading'" state="loading"/><StatePanel v-else-if="state==='error'" state="error" :message="error" @retry="load"/><StatePanel v-else-if="!result?.groups.length" state="empty" message="Bu filtrelerle karşılaştırılabilir mahalle bulunamadı."/><template v-else><div class="chart-bars mb-16"><div v-for="g in result.groups" :key="g.group_key" class="chart-bar-row"><span class="chart-bar-label" :title="g.group_label">{{ g.group_label }}</span><div class="chart-bar-track"><div class="chart-bar-fill" :style="{width:`${g.listing_count/maxCount*100}%`}"/></div><span class="chart-bar-value">{{ numberTR(g.listing_count) }} ilan</span></div></div><div class="table-wrap"><table><thead><tr><th>Mahalle</th><th>İlan sayısı</th><th>Ortalama fiyat</th><th>Medyan fiyat</th><th>Ort. m² fiyatı</th><th>Medyan m² fiyatı</th><th>Alan türü</th></tr></thead><tbody><tr v-for="g in result.groups" :key="g.group_key"><td class="table-primary">{{ g.group_label }}</td><td>{{ numberTR(g.listing_count) }}</td><td>{{ money(g.average_asking_price) }}</td><td>{{ money(g.median_asking_price) }}</td><td>{{ money(g.average_price_per_m2) }}</td><td>{{ money(g.median_price_per_m2) }}</td><td>{{ g.area_type==='net'?'Net m²':g.area_type==='gross'?'Brüt m²':g.area_type==='parcel'?'Parsel m²':'—' }}</td></tr></tbody></table></div><p class="panel-footnote">{{ result.reliability_note }} {{ result.price_basis }}</p></template></section></template>

